sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_style;
uniform float amzp_scale;
uniform float amzp_angle;
uniform float2 amzp_position;
uniform float2 amzp_stretch;
uniform float amzp_alpha;
uniform float amzp_hardness;
uniform float amzp_blendMode;
uniform float amzp_alphaComp;
layout(color) uniform half4 amzp_tint;
uniform float amzp_grain;
uniform float amzp_grime;
uniform float amzp_bumpSize;
uniform float amzp_lightAng;
uniform float amzp_shine;
uniform float amzp_rivSize;
uniform float amzp_rivSpaceX;
uniform float amzp_rivSpaceY;
uniform float amzp_rivStagger;
uniform float amzp_rivHeight;
uniform float amzp_rivShadow;
uniform float amzp_gradMap;
layout(color) uniform half4 amzp_gmFg;
layout(color) uniform half4 amzp_gmBg;
uniform float amzp_overdrawOn;
    float2 nmRot(float2 q, float a) { float c = cos(a), s = sin(a); return float2(c * q.x - s * q.y, s * q.x + c * q.y); }
    float h21(float2 p) { p = fract(p * float2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }
    float vnoise(float2 p) {
        float2 i = floor(p), f = fract(p);
        float2 u = f * f * (3.0 - 2.0 * f);
        return mix(mix(h21(i), h21(i + float2(1.0, 0.0)), u.x), mix(h21(i + float2(0.0, 1.0)), h21(i + float2(1.0, 1.0)), u.x), u.y);
    }
    float fbm(float2 p) {
        float s = 0.0, a = 0.5;
        for (int i = 0; i < 5; i++) { s += a * vnoise(p); p = p * 2.03 + float2(17.1, 9.7); a *= 0.5; }
        return s;
    }
    float3 brushed(float2 q) {
        float g = 0.0, l = 0.0, a = 1.0;
        for (int i = 0; i < 4; i++) {
            float k = pow(1.9, float(i));
            g += a * (vnoise(q * float2(0.9, 70.0) * k + float(i) * 13.7) - 0.5);
            l += a * (vnoise(q * float2(0.7, 0.06) * k + float(i) * 7.3) - 0.5);
            a *= 0.6;
        }
        g *= clamp(amzp_grain, 0.0, 3.0);
        float L = exp(2.6 * l - 1.2), G = exp(1.2 * g - 1.5);
        float v = min(0.1 * G + 0.2 * L + 2.0 * G * L, 1.0);
        v = pow(max(v, 0.0), 1.0 / 2.2);
        return float3(v);
    }
    float hRivet(float2 q, float r) {
        float2 P = q * 100.0;
        float2 cell = max(float2(amzp_rivSpaceX, amzp_rivSpaceY), float2(2.0));
        float row = floor(P.y / cell.y);
        P.x += mod(row, 2.0) * clamp(amzp_rivStagger, 0.0, 1.0) * cell.x;
        float2 c = mod(P, cell) - 0.5 * cell;
        float d = length(c) / max(amzp_rivSize, 0.5);
        return d < 1.0 ? sqrt(1.0 - d * d) : 0.0;
    }
    float hDiamond(float2 q, float r) {
        float2 id = floor(q), c = fract(q) - 0.5;
        float s = mod(id.x + id.y, 2.0) < 1.0 ? 1.0 : -1.0;
        float2 k = nmRot(c, s * 0.7854);
        float e = length(float2(k.x / (r * 1.45), k.y / (r * 0.32)));
        return e < 1.0 ? pow(1.0 - e * e, 0.6) : 0.0;
    }
    float hgt(float2 q, float r) { return int(amzp_style) == 1 ? hRivet(q, r) : hDiamond(q, r); }
    float3 plate(float2 q) {
        float r = int(amzp_style) == 1 ? max(amzp_rivSize, 0.5) / 100.0 : clamp(amzp_bumpSize, 0.05, 0.48);
        float e = 0.004;
        float h0 = hgt(q, r);
        float2 gr = float2(hgt(q + float2(e, 0.0), r) - hgt(q - float2(e, 0.0), r), hgt(q + float2(0.0, e), r) - hgt(q - float2(0.0, e), r)) / (2.0 * e);
        float la = radians(amzp_lightAng);
        float3 Ld = normalize(float3(cos(la), sin(la), 1.2));
        float3 n = normalize(float3(-gr * (int(amzp_style) == 1 ? 0.6 * r * clamp(amzp_rivHeight, 0.0, 3.0) : 0.18), 1.0));
        float dif = dot(n, Ld);
        float sh = h0 > 0.0 ? 0.0 : hgt(q + float2(cos(la), sin(la)) * r * 0.22, r);
        float spec = pow(max(dot(reflect(-Ld, n), float3(0.0, 0.0, 1.0)), 0.0), 18.0) * clamp(amzp_shine, 0.0, 2.0);
        float micro = (vnoise(q * float2(3.0, 180.0)) - 0.5) * 0.08 * clamp(amzp_grain, 0.0, 3.0);
        float dirt = smoothstep(0.35, 0.85, fbm(q * 0.9 + 3.1)) * clamp(amzp_grime, 0.0, 1.0);
        float3 base = int(amzp_style) == 1 ? float3(0.50) : float3(0.56, 0.60, 0.66);
        float3 col = base + micro;
        col *= 1.0 + 1.3 * (dif - Ld.z);
        col *= 1.0 - (int(amzp_style) == 1 ? 0.6 * clamp(amzp_rivShadow, 0.0, 1.0) : 0.35) * sh;
        col += spec * (h0 > 0.0 ? 1.0 : 0.25);
        col = mix(col, col * float3(0.55, 0.5, 0.42), dirt);
        return clamp(col, 0.0, 1.0);
    }
    float4 nmGradMap(float4 fx) {
        if (!(amzp_gradMap>0.5)) return fx;
        float v = clamp(dot(fx.rgb, float3(0.299, 0.587, 0.114)), 0.0, 1.0);
        float4 pB = float4(amzp_gmBg.rgb * amzp_gmBg.a, amzp_gmBg.a), pF = float4(amzp_gmFg.rgb * amzp_gmFg.a, amzp_gmFg.a);
        return mix(pB, pF, v) * fx.a;
    }
    float4 nmBlend(float4 tex, float4 fx) {
        float4 f = clamp(fx * amzp_hardness, 0.0, 1.0) * clamp(amzp_alpha, 0.0, 1.0);
        float4 b = tex * clamp(amzp_alphaComp, 0.0, 1.0);
        float4 o;
        if (int(amzp_blendMode) == 0) o = f;
        else if (int(amzp_blendMode) == 1) o = float4(b.rgb * (f.rgb + (1.0 - f.a)), b.a);
        else if (int(amzp_blendMode) == 2) o = float4(b.rgb + f.rgb - b.rgb * f.rgb, b.a + f.a - b.a * f.a);
        else o = f + b * (1.0 - f.a);
        o = clamp(o, 0.0, 1.0);
        return float4(min(o.rgb, float3(o.a)), o.a);
    }
    void amzRender() {
        float4 texColor = amzTexture(0, amzScreenNorm());
        float pxs = screen.zw.x / max(screen.zw.x, 1.0);
        float2 p = (amzLayerNorm() - 0.5) * layer / pxs;
        p -= float2(amzp_position.x, -amzp_position.y);
        p = nmRot(p, -radians(amzp_angle));
        float2 q = p / (max(amzp_scale * 2.0, 0.002) * max(amzp_stretch, float2(0.01)) * 100.0);
        float3 m = int(amzp_style) == 0 ? brushed(q) : (int(amzp_style) == 1 ? plate(q) : plate(q * 1.4));
        m *= amzp_tint.rgb;
        float4 fx = nmGradMap(float4(m, 1.0));
        float4 o = nmBlend(texColor, fx);
        if (!(amzp_overdrawOn>0.5)) o *= texColor.a;
        amzOutput = o;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
